import fs from 'node:fs';

const file = process.argv[2];
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);

function truncate(s, n = 200) {
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

let prevTs = null;
for (const line of lines) {
  let entry;
  try { entry = JSON.parse(line); } catch { continue; }
  const ts = entry.timestamp || null;
  let gap = '';
  if (ts && prevTs) {
    const dt = (new Date(ts) - new Date(prevTs)) / 1000;
    if (dt > 30) gap = ` [+${dt.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;

  if (entry.attachment) {
    console.log(`${ts || ''}${gap} HOOK ${entry.attachment.hookName || entry.attachment.type}: ${truncate(entry.attachment.content, 100)}`);
    continue;
  }

  const msg = entry.message;
  if (!msg) continue;
  const role = msg.role;
  const content = msg.content;
  if (typeof content === 'string') {
    console.log(`${ts || ''}${gap} ${role}: ${truncate(content, 300)}`);
    continue;
  }
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block.type === 'text') {
        console.log(`${ts || ''}${gap} ${role} text: ${truncate(block.text, 300)}`);
      } else if (block.type === 'tool_use') {
        console.log(`${ts || ''}${gap} ${role} tool_use[${block.name}]: ${truncate(block.input, 200)}`);
      } else if (block.type === 'tool_result') {
        const c = Array.isArray(block.content) ? block.content.map(b => b.text || '').join(' ') : block.content;
        console.log(`${ts || ''}${gap} ${role} tool_result: ${truncate(c, 150)}`);
      } else if (block.type === 'thinking') {
        console.log(`${ts || ''}${gap} ${role} thinking: ${truncate(block.thinking, 150)}`);
      }
    }
  }
}

